package org.sleepwell.app;
import android.content.Context;
import java.io.*;
import java.util.UUID;
/** Called only on the existing ordered sonar storage worker, after the clip interval is checkpointed. */
final class SonarClipWriter {
 static void save(Context context,Store store,long session,SonarSoundClips.Clip clip,SonarClipPolicy policy)throws Exception{if(policy==null||!policy.enabled||clip==null||clip.pcm.length!=320000||clip.duration!=10000)throw new IllegalStateException("Contactless audio recordings were not consented");synchronized(SoundClips.LOCK){if(store.rows("SELECT id FROM sessions WHERE id=? AND end IS NULL AND sensor=? AND start<=?",Long.toString(session),SensorProvenance.SONAR,Long.toString(clip.start)).isEmpty()||!store.rows("SELECT session FROM tracking_pauses WHERE session=? AND end IS NULL",Long.toString(session)).isEmpty()||store.rows("SELECT time FROM epochs WHERE session=? AND time>=? LIMIT 1",Long.toString(session),Long.toString(clip.end)).isEmpty())throw new IllegalStateException("The captured clip no longer belongs to an active durable contactless interval");if(policy.budget.pruneOnce())try{SoundClips.prune(context,store);}catch(RuntimeException error){Prefs.put(context,"audioRetentionError","Expired audio cleanup needs attention.");}File root=new File(context.getFilesDir(),"clips");if(!root.isDirectory()&&!root.mkdirs())throw new IOException("Could not create recordings directory");String filename=session+"-"+clip.end+"-"+UUID.randomUUID()+".wav";File target=FileSafety.clip(context,filename),temporary=FileSafety.clip(context,"pending-"+UUID.randomUUID()+".wav");boolean committed=false;try{NoiseRecorder.writeWave(temporary,clip.pcm);try(RandomAccessFile sync=new RandomAccessFile(temporary,"rw")){sync.getFD().sync();}if(!temporary.renameTo(target))throw new IOException("Could not save the captured recording");store.clip(session,clip.end,filename,clip.peak,clip.duration);committed=true;policy.saved(clip.endNanos/1000000L);}finally{temporary.delete();if(!committed)target.delete();}}}
 private SonarClipWriter(){}
}
